public class ImgStatsTool {
  public class Stats { public string path {get;set;} public long bytes {get;set;} public string sha256 {get;set;} public int width {get;set;} public int height {get;set;} public double nonblack_fraction {get;set;} public double[] mean_rgb_nonblack {get;set;} public double mean_luma_nonblack {get;set;} }
  public class Diff { public string from {get;set;} public string to {get;set;} public long pixels {get;set;} public double[] mean_delta_rgb {get;set;} public double mean_delta_luma {get;set;} public double mean_abs_delta_luma {get;set;} }
  static byte[] ReadBgra(string path, out int w, out int h) {
    using var src = new Bitmap(path);
    w = src.Width; h = src.Height;
    using var bmp = new Bitmap(w, h, PixelFormat.Format32bppArgb);
    using (var g = Graphics.FromImage(bmp)) g.DrawImage(src, 0, 0, w, h);
    var rect = new Rectangle(0,0,w,h);
    var data = bmp.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
    try {
      var bytes = new byte[Math.Abs(data.Stride)*h];
      Marshal.Copy(data.Scan0, bytes, 0, bytes.Length);
      return bytes;
    } finally { bmp.UnlockBits(data); }
  }
  static string Sha(string path) { using var s=File.OpenRead(path); return Convert.ToHexString(SHA256.HashData(s)).ToLowerInvariant(); }
  static double Luma(byte r, byte g, byte b) { return 0.2126*r + 0.7152*g + 0.0722*b; }
