    File.WriteAllText(Path.Combine(baseDir,"quick-analysis.json"), JsonSerializer.Serialize(result, options));
    Console.WriteLine(JsonSerializer.Serialize(new {evidence=baseDir, copied=srcs.Count, luma=stats, comparisons=diffs, privateMeasurements=privateMeasurements}, options));
  }
